"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[48630],{17240:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>a,default:()=>m,frontMatter:()=>s,metadata:()=>r,toc:()=>d});var o=n(31085),h=n(71184);const s={sidebar_position:11,slug:"/bible/Judges/Judges_11",title:"Judges 11",hide_table_of_contents:!0},a="Judges",r={id:"bible/Judges/Judges 11",title:"Judges 11",description:"Chapter 11",source:"@site/docs/bible/Judges/Judges 11.md",sourceDirName:"bible/Judges",slug:"/bible/Judges/Judges_11",permalink:"/docs/bible/Judges/Judges_11",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Judges/Judges 11.md",tags:[],version:"current",sidebarPosition:11,frontMatter:{sidebar_position:11,slug:"/bible/Judges/Judges_11",title:"Judges 11",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Judges 10",permalink:"/docs/bible/Judges/Judges_10"},next:{title:"Judges 12",permalink:"/docs/bible/Judges/Judges_12"}},i={},d=[{value:"Chapter 11",id:"chapter-11",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"judges",children:"Judges"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-11",children:"Chapter 11"}),"\n",(0,o.jsx)(t.p,{children:"Jephte is made ruler of the people of Galaad:  he first pleads their cause against the Ammonites; then making a vow obtains a signal victory; he performs his vow."}),"\n",(0,o.jsx)(n,{verse:1,children:"There was at that time Jephte, the Galaadite, a most valiant man, and a warrior, the son of a woman that was a harlot, and his father was Galaad."}),"\n",(0,o.jsx)(n,{verse:2,children:"Now Galaad had a wife of whom he had sons: who, after they were grown up, thrust out Jephte, saying: Thou canst not inherit in the house of our father, because thou art born of another mother."}),"\n",(0,o.jsx)(n,{verse:3,children:"Then he fled and avoided them, and dwelt in the land of Tob: and there were gathered to him needy men and robbers, and they followed him as their prince."}),"\n",(0,o.jsx)(n,{verse:4,children:"In those days the children of Ammon made war against Israel."}),"\n",(0,o.jsx)(n,{verse:5,children:"And as they pressed hard upon them, the ancients of Galaad went to fetch Jephte out of the land of Tob to help them:"}),"\n",(0,o.jsx)(n,{verse:6,children:"And they said to him: Come thou, and be our prince, and fight against the children of Ammon."}),"\n",(0,o.jsx)(n,{verse:7,children:"And he answered them: Are not you the men that hated me, and cast me out of my father's house, and now you are come to me, constrained by necessity?"}),"\n",(0,o.jsx)(n,{verse:8,children:"And the princes of Galaad said to Jephte: For this cause we are now come to thee, that thou mayst go with us, and fight against the children of Ammon, and be head over all the inhabitants of Galaad."}),"\n",(0,o.jsx)(n,{verse:9,children:"Jephte also said to them: If you be come to me sincerely, that I should fight for you against the children of Ammon, and the Lord shall deliver them into my hand, shall I be your prince?"}),"\n",(0,o.jsx)(n,{verse:10,children:"They answered him: The Lord, who heareth these things, he himself is mediator and witness that we will do as we have promised."}),"\n",(0,o.jsx)(n,{verse:11,children:"Jephte therefore went with the princes of Galaad, and all the people made him their prince. And Jephte spoke all his words before the Lord in Maspha."}),"\n",(0,o.jsx)(n,{verse:12,children:"And he sent messengers to the king of the children of Ammon, to say in his name: What hast thou to do with me, that thou art come against me, to waste my land?"}),"\n",(0,o.jsx)(n,{verse:13,children:"And he answered them: Because Israel took away my land, when he came up out of Egypt, from the confines of the Arnon unto the Jaboc and the Jordan: now, therefore, restore the same peaceably to me."}),"\n",(0,o.jsx)(n,{verse:14,children:"And Jephte again sent word by them, and commanded them to say to the king of Ammon:"}),"\n",(0,o.jsx)(n,{verse:15,children:"Thus saith Jephte: Israel did not take away the land of Moab, nor the land of the children of Ammon:"}),"\n",(0,o.jsx)(n,{verse:16,children:"But when they came up out of Egypt, he walked through the desert to the Red Sea, and came into Cades."}),"\n",(0,o.jsx)(n,{verse:17,children:"And he sent messengers to the king of Edom, saying: Suffer me to pass through thy land. But he would not condescend to his request. He sent also to the king of Moab, who, likewise, refused to give him passage. He abode, therefore, in Cades,"}),"\n",(0,o.jsx)(n,{verse:18,children:"And went round the land of Edom at the side, and the land of Moab: and came over against the east coast of the land of Moab, and camped on the other side of the Arnon: and he would not enter the bounds of Moab."}),"\n",(0,o.jsx)(n,{verse:19,children:"So Israel sent messengers to Sehon, king of the Amorrhites, who dwelt in Hesebon, and they said to him: Suffer me to pass through thy land to the river."}),"\n",(0,o.jsx)(n,{verse:20,children:"But he, also despising the words of Israel, suffered him not to pass through his borders: but gathering an infinite multitude, went out against him to Jasa, and made strong opposition."}),"\n",(0,o.jsx)(n,{verse:21,children:"And the Lord delivered him, with all his army, into the hands of Israel, and he slew him, and possessed all the land of the Amorrhite, the inhabitant of that country,"}),"\n",(0,o.jsx)(n,{verse:22,children:"And all the coasts thereof from the Arnon to the Jaboc, and from the wilderness to the Jordan."}),"\n",(0,o.jsx)(n,{verse:23,children:"So the Lord, the God of Israel, destroyed the Amorrhite, his people of Israel fighting against him, and wilt thou now possess his land?"}),"\n",(0,o.jsx)(n,{verse:24,children:"Are not those things which thy god Chamos possesseth, due to thee by right? But what the Lord our God hath obtained by conquest, shall be our possession:"}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Chamos...The idol of the Moabites and Ammonites. He argues from their opinion, who thought they had a just title to the countries which they imagined they had conquered by the help of their gods: how much more then had Israel in indisputable title to the countries which God, by visible miracles, had conquered for them."})}),"\n",(0,o.jsx)(n,{verse:25,children:"Unless, perhaps, thou art better than Balac, the son of Sephor, king of Moab: or canst shew that he strove against Israel, and fought against him,"}),"\n",(0,o.jsx)(n,{verse:26,children:"Whereas he hath dwelt in Hesebon, and the villages thereof, and in Aroer, and its villages, and in all the cities near the Jordan, for three hundred years. Why have you for so long a time attempted nothing about this claim?"}),"\n",(0,o.jsx)(n,{verse:27,children:"Therefore I do not trespass against thee, but thou wrongest me by declaring an unjust war against me. The Lord be judge, and decide this day, between Israel and the children of Ammon."}),"\n",(0,o.jsx)(n,{verse:28,children:"And the king of the children of Ammon would not hearken to the words of Jephte, which he sent him by the messengers."}),"\n",(0,o.jsx)(n,{verse:29,children:"Therefore the spirit of the Lord came upon Jephte, and going round Galaad, and Manasses, and Maspha of Galaad, and passing over from thence to the children of Ammon,"}),"\n",(0,o.jsx)(n,{verse:30,children:"He made a vow to the Lord, saying: If thou wilt deliver the children of Ammon into my hands,"}),"\n",(0,o.jsx)(n,{verse:31,children:"Whosoever shall first come forth out of the doors of my house, and shall meet me, when I return in peace from the children of Ammon, the same will I offer a holocaust to the Lord."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Whosoever, etc...Some are of opinion, that the meaning of this vow of Jephte, was to consecrate to God whatsoever should first meet him, according to the condition of the thing; so as to offer it up as a holocaust, if it were such a thing as might be offered by the law; or to devote it otherwise to God, if it were not such as the law allowed to be offered in sacrifice. And therefore they think the daughter of Jephte was not slain by her father, but only consecrated to perpetual virginity. But the common opinion followed by the generality of the holy fathers and divines is, that she was offered as a holocaust, in consequence of her father's vow: and that Jephte did not sin, at least not mortally, neither in making, nor in keeping, his vow: since he is no ways blamed for it in scripture; and was even inspired by God himself to make the vow (as appears from ver. 29, 30) in consequence of which he obtained the victory; and therefore he reasonably concluded that God, who is the master of life and death, was pleased on this occasion to dispense with his own law; and that it was the divine will he should fulfil his vow."})}),"\n",(0,o.jsx)(n,{verse:32,children:"And Jephte passed over to the children of Ammon to fight against them: and the Lord delivered them into his hands."}),"\n",(0,o.jsx)(n,{verse:33,children:"And he smote them from Aroer till you come to Mennith, twenty cities, and as far as Abel, which is set with vineyards, with a very great slaughter: and the children of Ammon were humbled by the children of Israel."}),"\n",(0,o.jsx)(n,{verse:34,children:"And when Jephte returned into Maspha, to his house, his only daughter met him with timbrels and with dances: for he had no other children."}),"\n",(0,o.jsx)(n,{verse:35,children:"And when he saw her, he rent his garments, and said: Alas! my daughter, thou hast deceived me, and thou thyself art deceived: for I have opened my mouth to the Lord, and I can do no other thing."}),"\n",(0,o.jsx)(n,{verse:36,children:"And she answered him: My father, if thou hast opened thy mouth to the Lord, do unto me whatsoever thou hast promised, since the victory hath been granted to thee, and revenge of thy enemies."}),"\n",(0,o.jsx)(n,{verse:37,children:"And she said to her father: Grant me only this, which I desire: Let me go, that I may go about the mountains for two months, and may bewail my virginity with my companions."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: Bewail my virginity...The bearing of children was much coveted under the Old Testament, when women might hope that from some child of theirs, the Saviour of the world might one day spring. But under the New Testament virginity is preferred. 1 Cor. 7.35."})}),"\n",(0,o.jsx)(n,{verse:38,children:"And he answered her: Go. And he sent her away for two months. And when she was gone with her comrades and companions, she mourned her virginity in the mountains."}),"\n",(0,o.jsx)(n,{verse:39,children:"And the two months being expired, she returned to her father, and he did to her as he had vowed, and she knew no man. From thence came a fashion in Israel, and a custom has been kept:"}),"\n",(0,o.jsx)(n,{verse:40,children:"That, from year to year, the daughters of Israel assemble together, and lament the daughter of Jephte the Galaadite, for four days."})]})}function m(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>r});var o=n(14041);const h={},s=o.createContext(h);function a(e){const t=o.useContext(s);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);